/* Persistent file/folder queue. Traversal is iterative and checkpoints complete turns. */
#define QBYTES 4096
static char qnames[ENTRIES][13];static u8 qattrs[ENTRIES];static TreeState qtree;static u16 qtreefail,qdirs;
static unsigned qcount,qnext,qok,qfail,qside;static u32 qpeer;static char qlocal[64],qremote[64];static u8 qrecord[QBYTES];static int q_running;
static char saved_selection[ENTRIES][13],saved_caret[13];static unsigned saved_count;
static void keep_selection(HWND box,Item*items,unsigned n){unsigned i;LRESULT caret;saved_count=0;saved_caret[0]=0;caret=SendMessageA(box,LB_GETCARETINDEX,0,0);if(caret>=0&&(unsigned)caret<n)textcopy(saved_caret,items[caret].name);for(i=0;i<n;i++)if(SendMessageA(box,LB_GETSEL,i,0)>0&&saved_count<ENTRIES)textcopy(saved_selection[saved_count++],items[i].name);}
static void restore_selection(HWND box,Item*items,unsigned n){unsigned i,j;SendMessageA(box,LB_SETSEL,FALSE,-1);for(i=0;i<n;i++){for(j=0;j<saved_count;j++)if(same(items[i].name,saved_selection[j]))SendMessageA(box,LB_SETSEL,TRUE,i);if(same(items[i].name,saved_caret))SendMessageA(box,LB_SETCARETINDEX,i,FALSE);}}
static void queuepath(char*out){textcopy(out,exedir);textcopy(out+slen(out),"\\LLQUEUE.DAT");}
static int relative_valid(const char*p){return relvalid(p);}
static int queue_store(void){char p[260],tmp[260];HANDLE f;DWORD n;int ok;unsigned i;zero(qrecord,QBYTES);copy(qrecord,"LLQ2",4);set16(qrecord+4,qside);set16(qrecord+6,qcount);set16(qrecord+8,qnext);set16(qrecord+10,qok);set16(qrecord+12,qfail);set32(qrecord+16,qpeer);textcopy((char*)qrecord+20,qlocal);textcopy((char*)qrecord+84,qremote);for(i=0;i<qcount;i++)copy(qrecord+148+i*13,qnames[i],13);copy(qrecord+3476,qattrs,256);tree_pack(qrecord+3732,&qtree);set16(qrecord+3832,qtreefail);set16(qrecord+3834,qdirs);set32(qrecord+4092,crcstep(0xffffffffUL,qrecord,4092)^0xffffffffUL);queuepath(p);textcopy(tmp,exedir);textcopy(tmp+slen(tmp),"\\LLQUEUE.NEW");f=CreateFileA(tmp,GENERIC_WRITE,0,0,CREATE_ALWAYS,FILE_ATTRIBUTE_NORMAL,0);if(f==INVALID_HANDLE_VALUE)return 0;ok=WriteFile(f,qrecord,QBYTES,&n,0)&&n==QBYTES&&FlushFileBuffers(f);if(!CloseHandle(f))ok=0;if(!ok)return 0;if(GetFileAttributesA(p)!=0xffffffffUL&&!DeleteFileA(p))return 0;return MoveFileA(tmp,p)!=0;}
static int queue_read(const char*leaf){char p[260];HANDLE f;DWORD n=0;unsigned crcpos;textcopy(p,exedir);textcopy(p+slen(p),"\\");textcopy(p+slen(p),leaf);f=CreateFileA(p,GENERIC_READ,FILE_SHARE_READ,0,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,0);if(f==INVALID_HANDLE_VALUE)return 0;if(!ReadFile(f,qrecord,QBYTES,&n,0))n=0;CloseHandle(f);if(n==3480&&qrecord[3]=='1')crcpos=3476;else if(n==QBYTES&&qrecord[3]=='2')crcpos=4092;else return 0;return qrecord[0]=='L'&&qrecord[1]=='L'&&qrecord[2]=='Q'&&get32(qrecord+crcpos)==(crcstep(0xffffffffUL,qrecord,crcpos)^0xffffffffUL);}
static int queue_load(void){unsigned i;if(!queue_read("LLQUEUE.NEW")&&!queue_read("LLQUEUE.DAT"))return 0;if(get16(qrecord+4)>1||get16(qrecord+6)>ENTRIES||get16(qrecord+8)>get16(qrecord+6)||qrecord[83]||qrecord[147]||!relvalid((char*)qrecord+20)||!relvalid((char*)qrecord+84))return 0;qside=get16(qrecord+4);qcount=get16(qrecord+6);qnext=get16(qrecord+8);qok=get16(qrecord+10);qfail=get16(qrecord+12);qpeer=get32(qrecord+16);textcopy(qlocal,(char*)qrecord+20);textcopy(qremote,(char*)qrecord+84);zero(qattrs,sizeof(qattrs));zero(&qtree,sizeof(qtree));qdirs=qtreefail=0;if(qrecord[3]=='2'){copy(qattrs,qrecord+3476,256);if(!tree_unpack(&qtree,qrecord+3732))return 0;qtreefail=get16(qrecord+3832);qdirs=get16(qrecord+3834);}for(i=0;i<qcount;i++){if(qrecord[148+i*13+12]||!valid((char*)qrecord+148+i*13)||(qattrs[i]&~16))return 0;textcopy(qnames[i],(char*)qrecord+148+i*13);}return 1;}
static void queue_summary(void){char b[160];textcopy(b,"Batch: ");numberstr(b+slen(b),qok);textcopy(b+slen(b)," copied, ");numberstr(b+slen(b),qfail);textcopy(b+slen(b)," failed/skipped, ");numberstr(b+slen(b),qcount-qnext);textcopy(b+slen(b)," pending");if(qdirs){textcopy(b+slen(b)," | folders ");numberstr(b+slen(b),qdirs);}if(qnext<qcount)textcopy(b+slen(b)," - F4 resumes");gui_status(b);logline(b);}
static int queue_folders(void){char p[260],part[13];unsigned i=0,j;DWORD a;if(qpeer!=peer_ip||!relvalid(qlocal)||!relvalid(qremote))return 0;if(!win_tree_full(p,"",qlocal))return 0;a=GetFileAttributesA(p);if(a==0xffffffffUL||!(a&16))return 0;while(remoterel[0]){if(!remoteop(CHDIR,"..",0,OK))return 0;up(remoterel);}while(qremote[i]){j=0;while(qremote[i]&&qremote[i]!='\\')part[j++]=qremote[i++];part[j]=0;if(!remoteop(CHDIR,part,0,OK))return 0;if(!descend(remoterel,part))return 0;if(qremote[i])i++;}textcopy(localrel,qlocal);localrefresh();return 1;}
static void queue_tree_fail(int st){qfail++;logline(qtree.rel);lognum("Folder item status",st);}
/* One complete tree operation; -1 is a broken stream, 0/1 ordinary progress. */
static int queue_tree_step(void){char remote[64],full[260],leaf[13],saved[260];u8 e[22];int st,k,ok;if(!reljoin(remote,qremote,qtree.rel)){queue_tree_fail(INVALID);tree_leave(&qtree);return 0;}
 if(qtree.phase==TP_MKDIR){if(qside)st=win_tree_mkdir(qlocal,qtree.rel);else{if(!tree_request(TC_MKDIR,remote,0))return -1;st=statusin(RESULT);if(st<0)return -1;}if(st==OK){qdirs++;qtree.phase=TP_SCAN;}else{queue_tree_fail(st);tree_leave(&qtree);}return 1;}
 if(qtree.phase==TP_SCAN){if(qside){if(!tree_request(TC_SCAN,remote,qtree.index[qtree.depth-1]))return -1;k=framein();if(k==ENTRY&&plen==22&&!payload[12]&&valid((char*)payload)){copy(e,payload,22);st=1;}else if(k==RESULT&&plen==2){st=get16(payload)==OK?0:(get16(payload)==TREE_SKIP?-2:-1);}else return -1;}else st=win_tree_scan(qlocal,qtree.rel,qtree.index[qtree.depth-1],e);if(st>0){if(!tree_child(&qtree,(char*)e,e[17]))queue_tree_fail(INVALID);}else if(st==-2){queue_tree_fail(INVALID);qtree.index[qtree.depth-1]++;}else{if(st<0)queue_tree_fail(IOERR);tree_leave(&qtree);}return 1;}
 if(!win_tree_parent(full,leaf,qlocal,qtree.rel)){queue_tree_fail(IOERR);tree_file_done(&qtree);return 0;}textcopy(saved,basedir);textcopy(basedir,full);st=IOERR;
 if(qside){if(!tree_request(TC_GET,remote,0)){textcopy(basedir,saved);return -1;}k=framein();if(k==PUT){ok=recvfile(leaf);st=ok?OK:last_transfer_status;if(transport_failed)st=-1;}else if(k==RESULT&&plen==2)st=get16(payload);else st=-1;}
 else{if(!tree_request(TC_PUT,remote,0)){textcopy(basedir,saved);return -1;}st=statusin(RESULT);if(st==OK)st=sendfile(leaf,leaf,0,0);}
 textcopy(basedir,saved);if(st<0)return -1;if(st==OK)qok++;else queue_tree_fail(st);tree_file_done(&qtree);return 1;}
/* busy remains held through every operation and final LIST refresh. */
static int queue_run(int retry){unsigned i,j;int st,allok=1;Item*items;HWND box;char p[260];if(peer==INVALID_SOCKET)return 0;if(retry){if(!queue_load()||!queue_folders()){gui_status("Cannot resume: connect the same peer and check folders.");return 0;}}else{qcount=qnext=qok=qfail=qdirs=0;zero(qattrs,sizeof(qattrs));zero(&qtree,sizeof(qtree));qside=active;qpeer=peer_ip;textcopy(qlocal,localrel);textcopy(qremote,remoterel);items=active?remotes:locals;box=active?rightbox:leftbox;for(i=0;i<(active?nr:nl);i++)if(SendMessageA(box,LB_GETSEL,i,0)>0&&valid(items[i].name)){qattrs[qcount]=items[i].attr&16;textcopy(qnames[qcount++],items[i].name);}if(!qcount){Item*it=selection();if(it&&valid(it->name)){qattrs[qcount]=it->attr&16;textcopy(qnames[qcount++],it->name);}}if(!qcount){gui_status("Select files or folders to copy.");return 0;}}
 if(!queue_store()){gui_status("Cannot save copy queue; transfer not started.");return 0;}cancel_queue=peer_cancelled=peer_state_changed=0;q_running=1;
 for(;qnext<qcount;){if(cancel_queue||peer_cancelled||peer_state_changed)break;transport_failed=0;if(qattrs[qnext]&16){if(!peer_tree){gui_status("Folder copying requires LiteLink 0.0.12 at both ends.");qfail++;qnext++;allok=0;}else{if(!qtree.phase){qtreefail=(u16)qfail;tree_begin(&qtree,qnames[qnext]);if(!queue_store()){allok=0;break;}}st=queue_tree_step();if(st<0){transport_failed=1;allok=0;break;}if(!qtree.phase){if(qfail==qtreefail){items=qside?remotes:locals;box=qside?rightbox:leftbox;for(j=0;j<(qside?nr:nl);j++)if(same(items[j].name,qnames[qnext]))SendMessageA(box,LB_SETSEL,FALSE,j);}qnext++;}}}
 else{if(qside)st=download(qnames[qnext],qnames[qnext],OK)?OK:(transport_failed?-1:last_transfer_status);else st=sendfile(qnames[qnext],qnames[qnext],0,0);if(st<0||transport_failed){allok=0;break;}if(st==OK){qok++;items=qside?remotes:locals;box=qside?rightbox:leftbox;for(j=0;j<(qside?nr:nl);j++)if(same(items[j].name,qnames[qnext]))SendMessageA(box,LB_SETSEL,FALSE,j);}else{qfail++;allok=0;}lognum(qnames[qnext],st);qnext++;}
 if(!queue_store()){allok=0;break;}if(remote_interactive&&!peer_poll()){transport_failed=1;allok=0;break;}}
 tree_findclose();q_running=0;if(qnext==qcount){queuepath(p);DeleteFileA(p);textcopy(p,exedir);textcopy(p+slen(p),"\\LLQUEUE.NEW");DeleteFileA(p);}else queue_store();localrefresh();if(peer!=INVALID_SOCKET&&!transport_failed){if(!remoterefresh())transport_failed=1;}if(transport_failed)lost();queue_summary();return allok&&qnext==qcount&&qfail==0;}
